export interface AstGrepRule {
  name: string;
  pattern: string;
  lang: string;
  produces: {
    edge_kind: "routes_to" | "renders";
    from_capture?: string;
    from_context?: "enclosing_function";
    to_capture?: string;
    to_template?: string;
    confidence: number;
  };
}

export interface LoadRulesOptions {
  bundledDir: string;
  projectRoot: string;
